<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('projects.manage');$pdo=db();$projectId=(int)($_GET['project_id']??$_POST['project_id']??0);$p=pm_fetch_project($pdo,$projectId);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'add');$uid=(int)($_POST['user_id']??0);if($action==='remove'&&$uid)$pdo->prepare('DELETE FROM project_members WHERE project_id=? AND user_id=?')->execute([$projectId,$uid]);elseif($uid)$pdo->prepare('INSERT INTO project_members(project_id,user_id,role_name,allocation_percent,hourly_cost) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE role_name=VALUES(role_name),allocation_percent=VALUES(allocation_percent),hourly_cost=VALUES(hourly_cost)')->execute([$projectId,$uid,trim((string)($_POST['role_name']??''))?:null,max(0,min(100,(int)($_POST['allocation_percent']??100))),max(0,(float)($_POST['hourly_cost']??0))]);redirect('project_members.php?project_id='.$projectId);}$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$q=$pdo->prepare('SELECT pm.*,u.name FROM project_members pm JOIN users u ON u.id=pm.user_id WHERE pm.project_id=? ORDER BY u.name');$q->execute([$projectId]);$members=$q->fetchAll();$pageTitle='Equipo · '.$p['name'];require __DIR__.'/includes/header.php';echo pm_project_tabs($projectId,'summary');?>
<section class="panel"><div class="panel-header"><div><h2>Equipo del proyecto</h2><span class="table-sub"><?=e($p['name'])?> · asignación y costo interno.</span></div><a class="btn btn-light btn-small" href="project_view.php?id=<?=$projectId?>">Volver</a></div><div class="panel-body"><form method="post" class="filters-wide"><?=csrf_field()?><input type="hidden" name="project_id" value="<?=$projectId?>"><input type="hidden" name="action" value="add"><label>Usuario<select name="user_id"><?php foreach($users as$u):?><option value="<?=$u['id']?>"><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Rol<input name="role_name" placeholder="Diseño, desarrollo, PM..."></label><label>Asignación %<input type="number" name="allocation_percent" min="0" max="100" value="100"></label><label>Costo/hora<input type="number" step="0.01" min="0" name="hourly_cost" value="0"></label><button class="btn btn-primary">AGREGAR / ACTUALIZAR</button></form></div><div class="table-wrap"><table><thead><tr><th>Miembro</th><th>Rol</th><th>Asignación</th><th>Costo/hora</th><th></th></tr></thead><tbody><?php foreach($members as$m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['role_name']?:'Miembro')?></td><td><?=(int)$m['allocation_percent']?>%</td><td><?=e(number_format((float)$m['hourly_cost'],2,',','.'))?></td><td><form method="post" onsubmit="return confirm('¿Quitar miembro?')"><?=csrf_field()?><input type="hidden" name="project_id" value="<?=$projectId?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="user_id" value="<?=$m['user_id']?>"><button class="btn btn-light btn-small">Quitar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/includes/footer.php';?>
